    if (type == null) {
        // If the type is null, return the result as is
        @SuppressWarnings("unchecked")
        T temp = (T) result;
        return temp;
    }
    // If the result is null, return null for any non-primitive type
    if (result == null) {
        return null;
    }
    // If the result is an instance of the given type, cast and return it
    if (type.isInstance(result)) {
        return type.cast(result);
    }
    // If the type is not compatible, throw an exception
    throw new ConversionException("Unsupported target type: " + type);
}

